{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '이걸 말한 것 자체가 유난이 아닐까'라고 물은 것은, 내담자가 자신의 필요를 표현하는 것조차 '충분하지 않다'는 핵심 믿음에 걸려 있는지 탐색하는 것. 내담자는 대화 내내 '그건 별거 아니에요', '다들 그렇지 않습니까'로 자신의 경험을 축소함."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "'유난'이라는 단어가 반복되는데, 이는 비난을 피하기 위해 높은 내면 기준을 충족해야 한다는 강박과 직결됨. 상담사가 '여기서도 그러고 계신 건 아닌지' 묻는 것은 이 강박이 상담실 안까지 확장되는지 확인하려는 것."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "내담자가 '바라면 안 되는 거예요. 바라면 유난이니까요'라고 한 것은, 쉬거나 인정을 바라는 것이 자격을 갖춘 다음의 일이라는 규칙을 그대로 드러냄. 상담사가 '지금 이 순간 여기서도' 묻는 것은 이 규칙이 상담 관계 안에서도 작동하는지 탐색하는 것."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "내담자는 상담 내내 자신의 고통과 경험을 '별거 아니다', '다들 그렇다'로 깎아내림. 이는 성과뿐 아니라 자신의 감정·필요 자체를 축소하는 양상과 같은 구조로, 상담사가 '유난이 아닐까' 하는 생각이 스쳤는지 묻는 것과 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0", "/situations/1"],
      "relevance": "내담자가 '놓치면 드러나잖아요'라고 한 것은, 기준을 낮추면(=놓치면) 사람들이 '그 정도밖에 안 되는 사람'임을 알게 된다는 부정적 가정과 일치. 상담사가 '본인한테 드러나는 것도 있나요'라고 물었을 때 내담자가 '제가 그 정도밖에 안 된다는 거잖아요'라고 답한 것이 이 가정을 확인시켜 줌."
    }
  ]
}

